package com.domesticservice.catalog.service;
import com.domesticservice.catalog.repository.support.NativeQueryExecutor;import com.domesticservice.common.web.ServiceHttpClient;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service public class RecoveryVoucherService {
 private final NativeQueryExecutor db;private final ServiceHttpClient identity;private final String secret;
 public RecoveryVoucherService(NativeQueryExecutor db,@Value("${clients.identity.base-url}")String url,@Value("${INTERNAL_SERVICE_TOKEN:}")String secret){this.db=db;identity=new ServiceHttpClient(url);this.secret=secret;}
 public void authorize(String key){if(secret.isBlank()||key==null||!java.security.MessageDigest.isEqual(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8),key.getBytes(java.nio.charset.StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Kết nối nội bộ không hợp lệ.");}
 @Transactional public Map<String,Object> issue(Map<String,Object>b){long booking=PriceQuoteService.number(b.get("bookingId")),customer=PriceQuoteService.number(b.get("customerId"));db.queryForObject("SELECT pg_advisory_xact_lock(?)",Object.class,booking);var prior=db.queryForList("SELECT * FROM promotions WHERE recovery_booking_id=?",booking);if(!prior.isEmpty()){if(((Number)prior.getFirst().get("owner_customer_id")).longValue()!=customer)throw PriceQuoteService.bad("Chủ voucher không khớp.");return prior.getFirst();}long id=db.insert("INSERT INTO promotions(promotion_code,promotion_name,description,start_at,end_at,discount_type,discount_value,usage_limit,owner_customer_id,recovery_booking_id) VALUES (?,?,?,now(),now()+interval '30 days','PERCENTAGE',5,1,?,?)","SORRY5-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT),"Ưu đãi xin lỗi 5%","Dành riêng cho bạn do nhân viên quên đơn #"+booking+". Một lượt sử dụng trong 30 ngày.",customer,booking);return db.queryForMap("SELECT * FROM promotions WHERE id=?",id);}
 public List<Map<String,Object>> mine(String token){long customer=ServiceHttpClient.userId(identity.authenticate(token,"CUSTOMER"));return db.queryForList("SELECT promotion_code AS code,promotion_name AS name,discount_value AS discount,description,end_at AS expires_at,used_count AS used_count,recovery_booking_id AS booking_id FROM promotions WHERE owner_customer_id=? ORDER BY id DESC",customer);}
}
